def norm_status(v):
    if v is None:
        return None
    if isinstance(v, (bool, np.bool_)):
        return "active" if v else "inactive"
    s = str(v).strip()
    if s == "" or s.lower() in ("na", "nan", "none"):
        return None
    sl = s.lower()
    if sl in ("true", "1"):
        return "active"
    if sl in ("false", "0"):
        return "inactive"
    return s

def norm_date(v):
    if v is None:
        return None
    if isinstance(v, pd.Timestamp):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if s == "" or s.lower() in ("na", "nan", "none"):
        return None
    try:
        return pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s[:10]

